export function parseNumber(value){const s=String(value??'').trim();if(!s)return null;const m=s.match(/^([+-]?(?:\d+(?:\.\d*)?|\.\d+))(?:\s*\/\s*([+-]?(?:\d+(?:\.\d*)?|\.\d+)))?$/);if(!m)return null;const n=Number(m[1]),d=m[2]===undefined?1:Number(m[2]);return d&&Number.isFinite(n/d)?n/d:null;}
export function gradeNumeric(value,expected){const a=parseNumber(value),b=parseNumber(expected);return a!==null&&b!==null&&Math.abs(a-b)<=1e-9*Math.max(1,Math.abs(b));}
export function remainingSeconds(session,now=Date.now()){return Math.max(0,Math.ceil((session.deadline-now)/1000));}
export function makeSession(mock,now=Date.now()){return {...mock,attemptId:`attempt-${now}-${Math.random().toString(36).slice(2,8)}`,startedAt:now,deadline:now+mock.durationMinutes*60000,answers:{},flags:{},current:0,status:'active'};}
export function finishSession(session,now=Date.now()){return {...session,status:'completed',finishedAt:now,results:session.questions.map(q=>({id:q.id,type:q.type,topic:q.topic,maxMarks:q.maxMarks,answer:session.answers[q.id]||'',score:q.type==='numeric'?(gradeNumeric(session.answers[q.id],q.answer)?q.maxMarks:0):null,status:q.type==='numeric'?'auto_checked':'needs_review'}))};}
export function validSession(s){return !!s&&s.status==='active'&&Array.isArray(s.questions)&&s.questions.length>0&&s.questions.length<=60&&s.questions.every(q=>q&&typeof q.id==='string'&&typeof q.statement==='string')&&Number.isFinite(s.deadline)&&Number.isInteger(s.current)&&s.current>=0&&s.current<s.questions.length&&s.answers&&typeof s.answers==='object'&&s.flags&&typeof s.flags==='object';}
